import React, { useState } from 'react';

function CartPage({ cart, onClearCart, onPlaceOrder }) {
    const [successMessage, setSuccessMessage] = useState(''); // State for success message
    const [showForm, setShowForm] = useState(false); // Toggle for user information form
    const [userInfo, setUserInfo] = useState({
        name: '',
        address: '',
        phone: '',
    }); // State for user information

    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const handlePlaceOrder = async () => {
        if (!userInfo.name || !userInfo.address || !userInfo.phone) {
            alert('Please fill in all the required information.');
            return;
        }

        try {
            await onPlaceOrder({ ...userInfo, totalAmount }); // Pass user info along with order
            setSuccessMessage('?? Your order has been placed successfully!');
            setTimeout(() => setSuccessMessage(''), 5000); // Clear the message after 5 seconds
            onClearCart(); // Clear the cart
            setShowForm(false); // Hide the form after placing the order
        } catch (err) {
            console.error('Error placing order:', err.message);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUserInfo((prevInfo) => ({
            ...prevInfo,
            [name]: value,
        }));
    };

    return (
        <div className="cart-container bg-gray-50 min-h-screen py-10 px-6">
            <h1 className="text-4xl font-bold text-green-600 text-center mb-8">
                Your Cart
            </h1>

            {/* Success message */}
            {successMessage && (
                <div className="bg-green-100 border border-green-500 text-green-700 p-4 rounded-lg shadow-md text-center mb-8">
                    <p className="text-lg font-semibold">{successMessage}</p>
                </div>
            )}

            {cart.length === 0 ? (
                <p className="text-center text-gray-500 text-lg">
                    Your cart is empty. Start shopping now!
                </p>
            ) : (
                <>
                    {/* Cart summary */}
                    <div className="cart-summary max-w-5xl mx-auto mt-10 bg-white p-6 rounded-lg shadow-lg">
                        <h2 className="text-2xl font-bold text-gray-800 mb-4">
                            Total Amount: <span className="text-green-600">${totalAmount.toFixed(2)}</span>
                        </h2>
                        {!showForm ? (
                            <button
                                onClick={() => setShowForm(true)} // Show form when clicked
                                className="w-full bg-green-500 hover:bg-green-600 text-white py-3 px-6 rounded-lg font-semibold transition duration-200 ease-in-out shadow-md"
                            >
                                Proceed to Checkout
                            </button>
                        ) : (
                            <div className="mt-6">
                                {/* Stylish User Information Form */}
                                <h3 className="text-lg font-bold text-gray-800 mb-4">
                                    Enter Your Information
                                </h3>
                                <form className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
                                    <div className="col-span-full">
                                        <label
                                            htmlFor="name"
                                            className="block text-sm font-medium text-gray-700"
                                        >
                                            Name
                                        </label>
                                        <input
                                            type="text"
                                            id="name"
                                            name="name"
                                            placeholder="Your Full Name"
                                            value={userInfo.name}
                                            onChange={handleInputChange}
                                            className="w-full mt-1 p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                            required
                                        />
                                    </div>
                                    <div className="col-span-full">
                                        <label
                                            htmlFor="address"
                                            className="block text-sm font-medium text-gray-700"
                                        >
                                            Address
                                        </label>
                                        <input
                                            type="text"
                                            id="address"
                                            name="address"
                                            placeholder="Your Address"
                                            value={userInfo.address}
                                            onChange={handleInputChange}
                                            className="w-full mt-1 p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                            required
                                        />
                                    </div>
                                    <div className="col-span-full">
                                        <label
                                            htmlFor="phone"
                                            className="block text-sm font-medium text-gray-700"
                                        >
                                            Phone Number
                                        </label>
                                        <input
                                            type="tel"
                                            id="phone"
                                            name="phone"
                                            placeholder="Your Phone Number"
                                            value={userInfo.phone}
                                            onChange={handleInputChange}
                                            className="w-full mt-1 p-3 border rounded-lg shadow-sm focus:ring-green-500 focus:border-green-500"
                                            required
                                        />
                                    </div>
                                </form>
                                <button
                                    onClick={handlePlaceOrder}
                                    className="mt-6 w-full bg-green-500 hover:bg-green-600 text-white py-3 px-6 rounded-lg font-semibold transition duration-200 ease-in-out shadow-md"
                                >
                                    Place Order
                                </button>
                            </div>
                        )}
                    </div>
                </>
            )}
        </div>
    );
}

export default CartPage;
